INSERT INTO "answers" VALUES('f46bf8bb-1d51-4c7e-b966-367a1a482b8b','4d25a756-d53a-4671-9b05-9c4324d6e1ca','4616e52f-719c-4cab-bea8-7a6f324246ac','In a world where snooze is survival and toast is a ticking clock, one student must make it to class with mismatched socks.',4,'2026-08-20T08:17:05.497Z','2026-08-20T08:17:05.497Z');
