INSERT INTO "votes" VALUES('ef50fdc0-99cb-436f-9f71-24862eb17bdf','b0fcbfb7-bd94-47ed-a036-b0b9fc523ff6','6ecae851-f8dd-43fa-b81b-f66eabaf7880',1,'2026-08-20T09:03:44.919Z');
INSERT INTO "replies" VALUES('018d2ef4-7b9e-4e82-a359-414734f1377c','6c5e067c-47e2-4131-8247-0ff251c83469','2844975e-8991-4303-9ec0-24a3ab6a774d','This is persuasive because it does not pretend it is easy. It names the loss and still chooses.','2026-08-20T08:40:54.868Z');
INSERT INTO "replies" VALUES('6ccd494c-1871-4e3c-a035-c82f7dee7151','fbeb76f2-bee0-44b5-840c-56184a0a5906','08bab6a9-c3ba-49f9-889e-b352665d0e50','I would push this one step further: what would you do when the strategy fails once? How would you revise it without abandoning it?','2026-08-20T08:40:54.877Z');
