INSERT INTO "replies" VALUES('ef83c75f-6b1b-4d0e-817e-06c63f1dd78c','dffa7997-586a-4390-9339-7a0f747819c3','2844975e-8991-4303-9ec0-24a3ab6a774d','This is persuasive because it does not pretend it is easy. It names the loss and still chooses.','2026-08-20T08:41:02.903Z');
INSERT INTO "replies" VALUES('83d2ad8f-19f6-4f94-a7a1-d4654246f4de','87ec6f19-bec3-434b-ab21-1af71c36bb0b','08bab6a9-c3ba-49f9-889e-b352665d0e50','Well put. The humor does not hide the point — it delivers it. That is hard to do and you did it.','2026-08-20T08:42:04.909Z');
INSERT INTO "replies" VALUES('d63061a8-5c6e-4385-9b2f-4da2411f2ac5','9f65e050-6ece-494d-984b-57e716f60263','08bab6a9-c3ba-49f9-889e-b352665d0e50','I like the clarity here. It would be even stronger with one concrete moment where you chose this and saw the result.','2026-08-20T08:43:49.935Z');
INSERT INTO "replies" VALUES('27b7079a-170a-4476-8622-8baf9f56054f','3232950c-e803-4fa4-99f6-5e9d6d749c56','7d3b502b-3864-4b9d-986b-bd3fa5ed3171','You articulate the quiet part: we often want more time but actually need less pressure. That distinction helps.','2026-08-20T09:00:14.880Z');
INSERT INTO "replies" VALUES('70127c26-0e52-4b1d-ac6a-e7f1586a180d','be0faed0-f024-46f4-a85a-b10f89a15131','08bab6a9-c3ba-49f9-889e-b352665d0e50','This is a strong angle — have you considered what happens if everyone adopted this reasoning at once?','2026-08-20T09:01:24.902Z');
INSERT INTO "replies" VALUES('8beb600e-7f24-4550-9ebb-91ad75b2a33d','ced07c78-220a-4226-8d6e-91ce9f1384b6','08bab6a9-c3ba-49f9-889e-b352665d0e50','I like the clarity here. It would be even stronger with one concrete moment where you chose this and saw the result.','2026-08-20T09:02:34.918Z');
INSERT INTO "replies" VALUES('99342b34-f72f-4e69-99ec-a37713829eab','cd187a07-fe41-4228-adf0-73e58dab0b87','7d3b502b-3864-4b9d-986b-bd3fa5ed3171','Agree on the core, but I would add one nuance: the cost is not just personal, it changes what others expect from you next time.','2026-08-20T09:05:29.937Z');
INSERT INTO "battles" VALUES('08465ab4-4e50-4c65-83ec-f27ac6ffbd8d','Which excuse for being late is more believable?','Traffic was unreal, they closed two lanes for no reason and I was stuck for 40 minutes.','My neighbor locked their keys inside and I stayed to help them call a locksmith.','44e5b143-556a-41b6-bfa1-5099f1365c18',4,1,'2026-08-20T08:17:05.580Z','active');
INSERT INTO "battles" VALUES('e9a4d77e-18ef-4ac9-98f0-acaa2f346159','Which superpower is more practical day to day?','Teleportation but you must have visited the place before and you arrive slightly dizzy for 10 seconds.','Time slowdown by 5x for 10 seconds, usable once per hour, no aging side effect.','44e5b143-556a-41b6-bfa1-5099f1365c18',2,4,'2026-08-20T08:17:05.581Z','active');
INSERT INTO "battles" VALUES('591ac545-4272-4d3e-89c8-a7574904984e','Which story opening hooks you more?','I did not realize the letter was for me until I saw my handwriting on the envelope.','The city went silent at 3:14 AM and every dog started staring in the same direction.','44e5b143-556a-41b6-bfa1-5099f1365c18',5,1,'2026-08-20T08:17:05.583Z','active');
