INSERT INTO "stories" VALUES('577439ad-547e-4707-8dfa-19b1e42f9a73','The Night Library','The library opened only at midnight, and only those who had lost something could see its entrance.','44e5b143-556a-41b6-bfa1-5099f1365c18','2026-08-20T08:17:05.584Z','open');
INSERT INTO "stories" VALUES('2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','The Last Delivery','Milo had delivered mail for 30 years, but today''s parcel was addressed to his own house from 1987.','44e5b143-556a-41b6-bfa1-5099f1365c18','2026-08-20T08:17:05.589Z','open');
INSERT INTO "story_entries" VALUES('efa50fca-d229-42d0-a2c3-cb0ab6446476','577439ad-547e-4707-8dfa-19b1e42f9a73','4616e52f-719c-4cab-bea8-7a6f324246ac','He pushed the door open and found a single desk with his name already written in the guest book.',0,'2026-08-20T08:17:05.586Z');
INSERT INTO "story_entries" VALUES('92a7e480-c067-4773-8ef7-47b7a9d2f87d','577439ad-547e-4707-8dfa-19b1e42f9a73','ad55daa6-9bc1-4269-9267-5e80c4006818','Inside the parcel was a key and a note: Do not open the attic, even if you hear knocking.',0,'2026-08-20T08:17:05.588Z');
INSERT INTO "story_entries" VALUES('a9951134-e88f-4dd1-8f0c-2e3fa821f471','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','4616e52f-719c-4cab-bea8-7a6f324246ac','He pushed the door open and found a single desk with his name already written in the guest book.',1,'2026-08-20T08:17:05.590Z');
INSERT INTO "story_entries" VALUES('805459d9-95f4-4a85-a950-cd3ce8876b60','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','ad55daa6-9bc1-4269-9267-5e80c4006818','Inside the parcel was a key and a note: Do not open the attic, even if you hear knocking.',0,'2026-08-20T08:17:05.592Z');
INSERT INTO "story_entries" VALUES('8a350cf9-beec-4d90-a845-0fbe580cda2a','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','7d3b502b-3864-4b9d-986b-bd3fa5ed3171','Outside, the city was holding its breath — no cars, no wind, just the faint sound of turning pages.',0,'2026-08-20T08:40:54.853Z');
INSERT INTO "story_entries" VALUES('65a154ea-609a-4ad7-a3b3-b1856e1a6f69','577439ad-547e-4707-8dfa-19b1e42f9a73','2844975e-8991-4303-9ec0-24a3ab6a774d','A second desk appeared across the room, with another name being written in ink that had not yet dried.',0,'2026-08-20T08:40:54.855Z');
INSERT INTO "story_entries" VALUES('5cfa55cd-02d2-4dbc-a982-62581ad024ea','577439ad-547e-4707-8dfa-19b1e42f9a73','0b34cc05-1eef-4e46-8175-8b13e2665d3b','Milo remembered the smell of that house in 1987: rain, old paper, and something sweet he could never name.',0,'2026-08-20T08:40:54.856Z');
INSERT INTO "story_entries" VALUES('a083d3da-34e4-4adc-91d6-00cea4d64f6d','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','2844975e-8991-4303-9ec0-24a3ab6a774d','Outside, the city was holding its breath — no cars, no wind, just the faint sound of turning pages.',0,'2026-08-20T08:45:34.945Z');
INSERT INTO "story_entries" VALUES('0e66f1ba-9a4b-4082-9c43-ef391849e4a6','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','0e17f525-46bb-473f-94bd-de006406d4b9','The library clock struck thirteen, and the shelves rearranged themselves when no one was looking.',0,'2026-08-20T08:52:35.024Z');
INSERT INTO "story_entries" VALUES('c1472f26-68d1-4180-910d-8ce807b7f2b2','2ad6b8cd-56d4-4975-ad7d-e4e89a94f950','0b34cc05-1eef-4e46-8175-8b13e2665d3b','The library clock struck thirteen, and the shelves rearranged themselves when no one was looking.',0,'2026-08-20T09:03:09.918Z');
INSERT INTO "confessions" VALUES('705f6bb8-534f-4309-8114-55f1b76055de','I pretend to understand every meeting and then google everything afterwards. It has worked for two years.','4616e52f-719c-4cab-bea8-7a6f324246ac','2026-08-20T08:17:05.593Z',0);
INSERT INTO "confessions" VALUES('0f2f8b4c-2ec9-4ebc-a849-be951a2352b6','I rehearse simple phone calls three times before dialing and still get nervous on the first ring.','4616e52f-719c-4cab-bea8-7a6f324246ac','2026-08-20T08:17:05.595Z',0);
INSERT INTO "confessions" VALUES('42503c49-e1dd-48b3-9559-84304b7b30f9','I keep all my unread books as if owning them means I have already read them.','4616e52f-719c-4cab-bea8-7a6f324246ac','2026-08-20T08:17:05.597Z',0);
